-- Isolated fixtures only; rollback leaves no synthetic product activity.
begin;
create function pg_temp.assert_true(condition boolean,label text) returns void language plpgsql as $$
begin if condition is not true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(statement text,code text,label text) returns void language plpgsql as $$
declare failed boolean:=false;
begin begin execute statement;exception when others then if sqlstate<>code then raise exception 'FAIL: %; expected %, got %',label,code,sqlstate;end if;failed:=true;end;
if not failed then raise exception 'FAIL: %; unexpectedly succeeded',label;end if;raise notice 'PASS: %',label;end;$$;
insert into auth.users(id,email_confirmed_at) values
('00000000-0000-4000-a000-000000000001',now()),('00000000-0000-4000-a000-000000000002',now()),('00000000-0000-4000-a000-000000000003',null);
update public.profiles set username=case id when '00000000-0000-4000-a000-000000000001' then 'alice' when '00000000-0000-4000-a000-000000000002' then 'bob' else 'unverified' end,display_name='Test maker';
insert into public.follows(follower_id,following_id) values('00000000-0000-4000-a000-000000000002','00000000-0000-4000-a000-000000000001');
select set_config('ark.input',jsonb_build_object('name','Shipped toolkit','tagline','A useful shipped developer toolkit','description',repeat('This project is ready to use. ',8),'launch_kind','software','release_url','https://EXAMPLE.test/package/#demo','category_id',(select id from public.categories where slug='developer-tools'),'technology_ids',jsonb_build_array((select id from public.technologies where slug='typescript')),'launch_confirmed',true)::text,true);

set local role anon;
select pg_temp.expect_error($q$select public.prepare_project('20000000-0000-4000-a000-000000000001',current_setting('ark.input')::jsonb)$q$,'42501','anonymous publication is denied');
select pg_temp.expect_error($q$select public.get_visible_project_media('{}')$q$,'42501','anonymous callers cannot request privileged media paths');
select pg_temp.expect_error($q$select * from public.notifications$q$,'42501','launch notifications are not public');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000003',true);
set local role authenticated;
select pg_temp.expect_error($q$select public.prepare_project('20000000-0000-4000-a000-000000000001',current_setting('ark.input')::jsonb)$q$,'42501','unverified email without authenticated GitHub is ineligible');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000001',true);
set local role authenticated;
select set_config('ark.project',public.prepare_project('20000000-0000-4000-a000-000000000001',current_setting('ark.input')::jsonb)->>'id',true);
select pg_temp.assert_true((select count(*)=0 from public.list_projects()),'staging drafts never enter public feeds');
select pg_temp.assert_true(public.prepare_project('20000000-0000-4000-a000-000000000001',current_setting('ark.input')::jsonb)->>'id'=current_setting('ark.project'),'prepare retries reuse one server-generated project');
select pg_temp.expect_error($q$select public.prepare_project('20000000-0000-4000-a000-000000000002',current_setting('ark.input')::jsonb)$q$,'23505','normalized duplicate destinations are rejected');
select pg_temp.expect_error($q$select public.publish_project(current_setting('ark.project')::uuid,3,'{}','{}',null)$q$,'22023','publication requires validated screenshots');
select set_config('ark.asset',public.reserve_project_upload(current_setting('ark.project')::uuid,'image/png',100)->>'id',true);
select pg_temp.expect_error($q$select public.claim_media_validation(current_setting('ark.asset')::uuid)$q$,'42501','authenticated users cannot mark screenshots validated');
select pg_temp.expect_error($q$select public.publish_project(current_setting('ark.project')::uuid,3,array[current_setting('ark.asset')::uuid],array['A screenshot'],current_setting('ark.asset')::uuid)$q$,'22023','raw staged uploads cannot be published');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',true);
set local role authenticated;
select pg_temp.expect_error($q$select public.get_my_upload(current_setting('ark.asset')::uuid)$q$,'42501','another maker cannot inspect upload reservations');
select pg_temp.expect_error($q$select public.reserve_project_upload(current_setting('ark.project')::uuid,'image/png',100)$q$,'42501','another maker cannot upload to a project');
select pg_temp.assert_true(public.get_my_project(current_setting('ark.project')::uuid) is null,'another maker cannot read the management DTO');
reset role;
set local role service_role;
select set_config('ark.lease',public.claim_media_validation(current_setting('ark.asset')::uuid)->>'lease_token',true);
select pg_temp.expect_error($q$select public.claim_media_validation(current_setting('ark.asset')::uuid)$q$,'40001','concurrent image validation acquires a lease');
select public.complete_media_validation(current_setting('ark.asset')::uuid,current_setting('ark.lease')::uuid,90,64,64);
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000001',true);
set local role authenticated;
select pg_temp.expect_error($q$select public.publish_project(current_setting('ark.project')::uuid,2,array[current_setting('ark.asset')::uuid],array['A screenshot'],current_setting('ark.asset')::uuid)$q$,'40001','stale publication payloads are rejected');
select public.publish_project(current_setting('ark.project')::uuid,3,array[current_setting('ark.asset')::uuid],array['The toolkit main screen'],current_setting('ark.asset')::uuid);
select pg_temp.assert_true((select count(*)=1 from public.list_projects()),'publication makes exactly one project public');
select pg_temp.assert_true((select release_url='https://example.test/package' from public.get_public_project(current_setting('ark.project')::uuid)),'publication uses trusted URL normalization');
select pg_temp.assert_true(public.publish_project(current_setting('ark.project')::uuid,3,array[current_setting('ark.asset')::uuid],array['The toolkit main screen'],current_setting('ark.asset')::uuid)=current_setting('ark.project')::uuid,'publication retries are idempotent');
select set_config('ark.published_at',public.get_my_project(current_setting('ark.project')::uuid)->'project'->>'published_at',true);
select public.set_profile_pin(current_setting('ark.project')::uuid,true);
select public.set_profile_pin(current_setting('ark.project')::uuid,true);
select pg_temp.assert_true((select count(*)=1 from public.profile_pins),'pin retries do not duplicate pins');
select pg_temp.expect_error($q$select public.edit_project(current_setting('ark.project')::uuid,3,current_setting('ark.input')::jsonb,array[current_setting('ark.asset')::uuid],array['Updated screenshot'],current_setting('ark.asset')::uuid)$q$,'40001','stale edits cannot overwrite a newer project');
select pg_temp.assert_true(public.edit_project(current_setting('ark.project')::uuid,4,current_setting('ark.input')::jsonb||'{"name":"Updated toolkit"}',array[current_setting('ark.asset')::uuid],array['Updated screenshot'],current_setting('ark.asset')::uuid)=5,'owner can update content and media transactionally');
select pg_temp.assert_true(public.get_my_project(current_setting('ark.project')::uuid)->'project'->>'published_at'=current_setting('ark.published_at'),'editing keeps the original publication timestamp');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.notifications),'initial publication sends one follower notification');
select pg_temp.expect_error($q$select public.edit_project(current_setting('ark.project')::uuid,5,current_setting('ark.input')::jsonb,array[current_setting('ark.asset')::uuid],array['Stolen screenshot'],current_setting('ark.asset')::uuid)$q$,'42501','another maker cannot edit the project');
select pg_temp.expect_error($q$select public.delete_project(current_setting('ark.project')::uuid,'Updated toolkit')$q$,'42501','another maker cannot delete the project');
reset role;
update public.projects set status='hidden' where id=current_setting('ark.project')::uuid;
set local role service_role;
select pg_temp.assert_true((select count(*)=0 from public.get_visible_project_media(array[current_setting('ark.project')::uuid])),'hidden work receives no fresh signed-media metadata');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000001',true);
set local role authenticated;
select public.edit_project(current_setting('ark.project')::uuid,5,current_setting('ark.input')::jsonb,array[current_setting('ark.asset')::uuid],array['Updated screenshot'],current_setting('ark.asset')::uuid);
select pg_temp.assert_true(public.get_my_project(current_setting('ark.project')::uuid)->'project'->>'status'='hidden','maker edits never unhide moderated content');
select pg_temp.expect_error($q$select public.publish_project(current_setting('ark.project')::uuid,6,array[current_setting('ark.asset')::uuid],array['Updated screenshot'],current_setting('ark.asset')::uuid)$q$,'22023','a maker cannot republish a hidden project');
select pg_temp.expect_error($q$select public.delete_project(current_setting('ark.project')::uuid,'wrong name')$q$,'22023','deletion requires the exact project name');
select public.delete_project(current_setting('ark.project')::uuid,'Shipped toolkit');
select public.delete_project(current_setting('ark.project')::uuid,'Shipped toolkit');
select pg_temp.assert_true((select count(*)=0 from public.list_projects()),'deletion immediately removes discovery visibility');
reset role;
select pg_temp.assert_true((select count(*)=1 from private.maintenance_jobs where dedupe_key='project-delete:'||current_setting('ark.project')),'deletion persists one retry-safe cleanup job');
select pg_temp.assert_true((select count(*)=0 from private.project_destinations),'deletion releases normalized launch destinations');
select pg_temp.assert_true((select withdrawn_at is not null from public.notifications where project_id=current_setting('ark.project')::uuid),'deletion withdraws project notifications');
set local role service_role;
select public.claim_media_jobs(10);
reset role;
select pg_temp.assert_true((select status='running' and attempts=1 from private.maintenance_jobs where dedupe_key='project-delete:'||current_setting('ark.project')),'cleanup jobs are durably leased');
select set_config('ark.job',(select id::text from private.maintenance_jobs where dedupe_key='project-delete:'||current_setting('ark.project')),true);
set local role service_role;
select pg_temp.assert_true(jsonb_array_length(public.media_job_objects(current_setting('ark.job')::uuid))=1,'deleted image objects are eligible for cleanup');
select public.finish_media_job(current_setting('ark.job')::uuid,1,false,'storage_cleanup_failed');
reset role;
select pg_temp.assert_true((select status='failed' and next_attempt_at>now() from private.maintenance_jobs where id=current_setting('ark.job')::uuid),'failed cleanup retains its payload and retries with backoff');
rollback;
